  function playHeroIntro(container) {
    const hero = container.querySelector("[data-hero]");
    if (!hero) return;
    const namespace = container.dataset.barbaNamespace;
    const svgs = Array.from(hero.querySelectorAll("[data-hero-svg]"));
    const mdEl = hero.querySelector("[data-hero-text-md]");
    const cptEls = hero.querySelectorAll("[data-hero-cpt]");
    const texts = hero.querySelectorAll("[data-hero-text]");
    const imgs = hero.querySelectorAll("[data-hero-img]");
    const btn = hero.querySelector("[data-hero-btn]");

    const tl = gsap.timeline();

    if (namespace === "home") {
      tl.add(addHeroSvgSlideReveal(svgs));
      if (btn) tl.add(addHeroBtnReveal(btn), 1.1);
      imgs.forEach((img) => tl.add(addHeroImageReveal(img), 1.2));
      // Custom EAD slide-down + LSM typewriter
      var heroEad = hero.querySelector('#hero-ead');
      var heroLsm = hero.querySelector('#hero-lsm');
      if (heroEad) {
        tl.to(heroEad, { opacity: 1, x: 0, y: 0, duration: 1.4, ease: 'power4.out' }, 0.8);
      }
      if (heroLsm) {
        var _letters = ['L','S','M','.'];
        _letters.forEach(function(_ch, _i) {
          tl.call(function(){ heroLsm.textContent += _ch; }, null, 2.0 + _i * 0.22);
        });
        tl.to(heroLsm, { borderRightColor: 'transparent', repeat: 5, yoyo: true, duration: 0.3, ease: 'steps(1)' }, 3.0);
        tl.set(heroLsm, { borderRight: 'none', paddingRight: '0' }, 4.6);
      }
      tl.add(addTextMdAnimation(mdEl), 1.2);
      cptEls.forEach((el) => tl.add(addCptAnimation(el), 1.2));
      texts.forEach((text) => tl.add(addTextBaseAnimation(text), 1.2));
    } else {
      tl.add(addSvgSlideReveal(svgs));
      if (namespace === "services") { imgs.forEach((img) => tl.add(addSvcImageReveal(img), 0)); }
      else { imgs.forEach((img) => tl.add(addImageReveal(img), 0)); }
      tl.add(addTextMdAnimation(mdEl), 0.375);
      cptEls.forEach((el) => tl.add(addCptAnimation(el), 0.5));
      texts.forEach((text) => tl.add(addTextBaseAnimation(text), 0.5));
      if (namespace === "404") tl.add(addHeroBtnReveal(btn), 0.5);
    }

    return tl;
  }

  //HOME Functions

  function initHomeHero(container) {
    const hero = container.querySelector("[data-hero]");
    if (!hero) return;
    const wrap = hero.querySelector("[data-hero-img]");
    if (!wrap) return;
    const imgs = Array.from(wrap.querySelectorAll("img"));
    if (!imgs.length) return;

    let currentIndex = 0;
    let zCounter = 1;

    gsap.set(imgs, { transformOrigin: "center center" });
    gsap.set(imgs[0], { zIndex: 1 });

    imgs.forEach((img) => {
      img.setAttribute("draggable", "false");
      img.style.userSelect = "none";
      img.style.webkitUserSelect = "none";
    });

    let maxTravel = 0;

    function recalculate() {
      const rect = hero.getBoundingClientRect();
      if (!rect.width) return;
      const paddingPx = parseFloat(getComputedStyle(hero).fontSize) * 1.25;
      maxTravel = Math.max(40, (rect.width - wrap.offsetWidth) / 2 - paddingPx); // ← min 40px travel
      const currentX = gsap.getProperty(wrap, "x");
      const clamped = Math.max(-maxTravel, Math.min(maxTravel, currentX));
      gsap.set(wrap, { x: clamped });
    }
    recalculate();

    const ro = new ResizeObserver(recalculate);
    ro.observe(hero);

    const onMouseMove = (e) => {
      const rect = hero.getBoundingClientRect();
      const centerX = rect.left + rect.width / 2;
      const relX = e.clientX - centerX;
      const normalized = relX / (rect.width / 2);
      const x = Math.max(-maxTravel, Math.min(maxTravel, normalized * maxTravel));
      gsap.to(wrap, { x, duration: 0.8, ease: "power3.out" });
    };

    const onClick = () => {
      const nextIndex = (currentIndex + 1) % imgs.length;
      zCounter++;
      gsap.set(imgs[nextIndex], { zIndex: zCounter });
      gsap.fromTo(imgs[nextIndex], { scale: 0, autoAlpha: 1 }, {
        scale: 1.01,
        autoAlpha: 1,
        duration: 0.5,
        ease: "power3.out"
      });
      currentIndex = nextIndex;
    };

    hero.addEventListener("mousemove", onMouseMove, { passive: true });
    wrap.addEventListener("click", onClick);

    return () => {
      hero.removeEventListener("mousemove", onMouseMove);
      wrap.removeEventListener("click", onClick);
      ro.disconnect();
      gsap.to(wrap, { x: 0, duration: 0.5 });
    };
  }

