  function initWorkImageHover(container) {
    const wrap = container.querySelector(".work_main_img_wrapper");
    if (!wrap) return null;

    const items = Array.from(wrap.querySelectorAll("[data-work-item]"));
    if (items.length < 2) return null;

    const imgs = items.map((el) => el.querySelector("img")).filter(Boolean);
    const overlays = items.map((el) => el.querySelector(".work_img_overlay")).filter(Boolean);

    if (overlays.length !== items.length) return null;

    const onEnter = (e) => {
      const activeIndex = items.indexOf(e.currentTarget);
      items.forEach((_, i) => {
        const isActive = i === activeIndex;
        gsap.to(overlays[i], { opacity: isActive ? 0 : 0.75, duration: 0.25 });
        gsap.to(imgs[i], {
          scale: isActive ? 1.1 : 1.01,
          duration: 0.25,
          ease: "power2.out"
        });
      });
    };

    const onLeave = () => {
      gsap.to(overlays, { opacity: 0, duration: 0.25 });
      gsap.to(imgs, { scale: 1, duration: 0.25 });
    };

    items.forEach((item) => {
      item.addEventListener("pointerenter", onEnter);
      item.addEventListener("pointerleave", onLeave);
    });
  }

  function initHomeWork(container) {
    const workMain = container.querySelector(".work_main_wrap");
    if (!workMain) return;

    const cleanupCursor = initCustomCursor(workMain, {
      svgColor: "var(--color-white)",
      textColor: "var(--color-black)",
      text: "View Project"
    });

    const img2 = workMain.querySelector(".work_collection_list_wrap.is-2");
    const img3 = workMain.querySelector(".work_collection_list_wrap.is-3");
    if (!img2 || !img3) return;

    const titleEl = workMain.querySelector("[data-work-title]");
    const numberEl = workMain.querySelector("[data-work-number]");
    const descEl = workMain.querySelector("[data-work-desc]");
    const yearEl = workMain.querySelector("[data-work-year]");
    const serviceEls = Array.from(workMain.querySelectorAll(".work_main_bottom_list_cpt"));

    const bgs = [
      workMain.querySelector(".work_main_bg.is-1"),
      workMain.querySelector(".work_main_bg.is-2"),
      workMain.querySelector(".work_main_bg.is-3"),
    ].filter(Boolean);

    const cases = [
    {
      title: "LUMEN",
      number: "01",
      desc: "Identity communication for a contemporary gallery defined by what it doesn't show.",
      year: "2026",
      services: ["Brand Identity", "Spatial Design", "Art Direction"],
    },
    {
      title: "C. Ground",
      number: "02",
      desc: "A real estate developer building with weight, permanence, and the city in mind.",
      year: "2026",
      services: ["Brand Identity", "Art Direction", "Digital Design"],
    },
    {
      title: "Modular",
      number: "03",
      desc: "A creative studio built to move between disciplines without losing form.",
      year: "2026",
      services: ["Brand Identity", "Art Direction", "Digital Design"],
    }, ];

    const CLOSED = "inset(0 50% 0 50%)";
    const OPEN = "inset(0 0% 0 0%)";

    gsap.set(bgs[0], { zIndex: 0, clipPath: OPEN });
    gsap.set(bgs[1], { zIndex: 1, clipPath: CLOSED });
    gsap.set(bgs[2], { zIndex: 2, clipPath: CLOSED });
    gsap.set([img2, img3], { clipPath: "inset(100% 0 0 0)", zIndex: 2, scale: 1.01 });

    let currentIndex = 0;
    let animating = false;

    function renderCase(i) {
      const c = cases[i];
      if (!c) return;
      if (titleEl) titleEl.textContent = c.title;
      if (numberEl) numberEl.textContent = c.number;
      if (descEl) descEl.textContent = c.desc;
      if (yearEl) yearEl.textContent = c.year;
      serviceEls.forEach((el, i) => {
        if (el) el.textContent = c.services[i] ?? "";
      });
    }

    function splitEl(el) {
      if (!el) return;
      if (el._split) {
        el._split.revert();
        el._split = null;
      }
      const split = new SplitText(el, {
        type: "lines",
        mask: "lines",
        linesClass: "split-line",
      });
      el._split = split;
      state.activeSplits.push(split);
    }

    function revertEl(el) {
      if (!el?._split) return;
      el._split.revert();
      el._split = null;
    }

    function revealBg(i) {
      const bg = bgs[i];
      if (!bg) return;
      gsap.killTweensOf(bg);
      gsap.fromTo(bg, { clipPath: CLOSED }, {
        clipPath: OPEN,
        duration: 0.75,
        ease: "power3.out"
      });
    }

    function hideBg(i) {
      const bg = bgs[i];
      if (!bg) return;
      gsap.killTweensOf(bg);
      gsap.to(bg, { clipPath: CLOSED, duration: 0.75, ease: "power3.inOut" });
    }

    function setBgsForIndex(targetIndex, prevIndex) {
      const goingForward = targetIndex > prevIndex;

      if (goingForward) {
        for (let i = prevIndex + 1; i <= targetIndex; i++) {
          revealBg(i);
        }
      } else {
        for (let i = prevIndex; i > targetIndex; i--) {
          hideBg(i);
        }
      }
    }

    let pendingUpdate = null;

    function updateCaseTo(targetIndex) {
      if (targetIndex === currentIndex) return;

      if (pendingUpdate) {
        pendingUpdate.kill();
        pendingUpdate = null;
      }

      const prevIndex = currentIndex;
      currentIndex = targetIndex;

      setBgsForIndex(targetIndex, prevIndex);

      const nodes = [descEl, yearEl, ...serviceEls].filter(Boolean);
      gsap.to(nodes, { autoAlpha: 0, duration: 0.25 });

      const oldLines = [
        ...(titleEl?._split?.lines || []),
        ...(numberEl?._split?.lines || []),
      ];
      if (oldLines.length) {
        gsap.killTweensOf(oldLines);
        gsap.to(oldLines, {
          yPercent: -120,
          duration: 0.7,
          ease: "power4.out",
        });
      }

      pendingUpdate = gsap.delayedCall(0.35, () => {
        revertEl(titleEl);
        revertEl(numberEl);
        renderCase(targetIndex);
        splitEl(titleEl);
        splitEl(numberEl);

        const newLines = [
          ...(titleEl?._split?.lines || []),
          ...(numberEl?._split?.lines || []),
        ];

        gsap.set(newLines, { yPercent: 120 });
        gsap.to(nodes, { autoAlpha: 1, duration: 0.25 });
        gsap.to(newLines, {
          yPercent: 0,
          duration: 0.7,
          ease: "power4.out",
        });
        pendingUpdate = null;
      });
    }

    let lastProgress = 0;

    function getTargetIndex(progress) {
      const goingDown = progress > lastProgress;

      const crossed = (threshold) => {
        return goingDown ?
          (lastProgress < threshold && progress >= threshold) :
          (lastProgress >= threshold && progress < threshold);
      };

      let newIndex = currentIndex;

      if (goingDown) {
        if (crossed(0.5)) newIndex = 1;
        if (crossed(0.999)) newIndex = 2;
      } else {
        if (crossed(0.5)) newIndex = 1;
        if (crossed(0.001)) newIndex = 0;
      }

      lastProgress = progress;

      return newIndex;
    }

    renderCase(0);
    splitEl(titleEl);
    splitEl(numberEl);

    const scrollTl = gsap.timeline({
      scrollTrigger: {
        trigger: workMain,
        start: "top top",
        end: "+=200%",
        scrub: true,
        pin: true,
        pinSpacing: true,
        invalidateOnRefresh: true,
        onUpdate(self) {
          const targetIndex = getTargetIndex(self.progress);
          if (targetIndex !== currentIndex) {
            updateCaseTo(targetIndex);
          }
        },
      },
    });

    scrollTl.to(img2, { clipPath: "inset(0% 0 0 0)", duration: 1, ease: "none" });
    scrollTl.to(img3, { clipPath: "inset(0% 0 0 0)", duration: 1, ease: "none" });

    return cleanupCursor;
  }

